use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Choice { pub label: String, pub weight: u32 }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Facet { pub key: String, pub choices: Vec<Choice> }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CatalogSpec { pub prefix: String, pub count: usize, pub facets: Vec<Facet>, pub max_combinations: usize }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Badge { pub ordinal: usize, pub title: String, pub traits: Vec<(String, String)> }
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CatalogError { InvalidConfig, InvalidGuarantee, CapacityExceeded, CombinationLimitExceeded }

pub fn titleize(input: &str) -> String {
    let leaf = input.rsplit('/').next().unwrap_or("");
    let stem = match leaf.rsplit_once('.') { Some((s, _)) => s, None => leaf };
    let mut out = String::new();
    let mut new_word = true;
    for c in stem.chars() {
        if c == '_' || c == '-' || c.is_ascii_whitespace() {
            if !out.is_empty() && !out.ends_with(' ') { out.push(' '); }
            new_word = true;
        } else {
            out.push(if new_word { c.to_ascii_uppercase() } else { c });
            new_word = false;
        }
    }
    while out.ends_with(' ') { out.pop(); }
    out
}

pub fn build_catalog(spec: &CatalogSpec, guarantees: &BTreeMap<usize, BTreeMap<String, String>>) -> Result<Vec<Badge>, CatalogError> {
    let mut keys = BTreeSet::new();
    let mut total = 1usize;
    for facet in &spec.facets {
        if facet.key.is_empty() || facet.choices.is_empty() || !keys.insert(facet.key.clone()) { return Err(CatalogError::InvalidConfig); }
        let mut labels = BTreeSet::new();
        for choice in &facet.choices {
            if choice.label.is_empty() || !labels.insert(choice.label.clone()) { return Err(CatalogError::InvalidConfig); }
        }
        total = total.checked_mul(facet.choices.len()).ok_or(CatalogError::InvalidConfig)?;
    }
    if spec.count != 0 && spec.max_combinations == 0 { return Err(CatalogError::InvalidConfig); }
    for (&index, forced) in guarantees {
        if index >= spec.count { return Err(CatalogError::InvalidGuarantee); }
        for (key, value) in forced {
            let facet = spec.facets.iter().find(|f| &f.key == key).ok_or(CatalogError::InvalidGuarantee)?;
            if !facet.choices.iter().any(|c| &c.label == value) { return Err(CatalogError::InvalidGuarantee); }
        }
    }
    if total > spec.max_combinations { return Err(CatalogError::CombinationLimitExceeded); }
    if spec.count > total { return Err(CatalogError::CapacityExceeded); }
    let mut combinations: Vec<(u64, Vec<String>)> = vec![(0, Vec::new())];
    for facet in &spec.facets {
        let mut next = Vec::with_capacity(combinations.len() * facet.choices.len());
        for (score, values) in combinations {
            for choice in &facet.choices {
                let mut v = values.clone();
                v.push(choice.label.clone());
                next.push((score + choice.weight as u64, v));
            }
        }
        combinations = next;
    }
    combinations.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    let mut used = BTreeSet::new();
    let mut result = Vec::with_capacity(spec.count);
    let base = titleize(&spec.prefix);
    for index in 0..spec.count {
        let forced = guarantees.get(&index);
        let position = combinations.iter().enumerate().find(|(p, (_, values))| {
            !used.contains(p) && forced.map_or(true, |rules| rules.iter().all(|(k, v)| {
                let i = spec.facets.iter().position(|f| &f.key == k).unwrap();
                &values[i] == v
            }))
        }).map(|(p, _)| p).ok_or(CatalogError::CapacityExceeded)?;
        used.insert(position);
        let values = &combinations[position].1;
        let traits = spec.facets.iter().zip(values).map(|(f, v)| (f.key.clone(), v.clone())).collect();
        let ordinal = index + 1;
        result.push(Badge { ordinal, title: format!("{} #{}", base, ordinal), traits });
    }
    Ok(result)
}

