#[path = "solution.rs"]
mod solution;

use solution::{build_catalog, titleize, CatalogError, CatalogSpec, Choice, Facet};
use std::collections::BTreeMap;

fn choice(label: &str, weight: u32) -> Choice {
    Choice { label: label.to_string(), weight }
}

fn facet(key: &str, choices: Vec<Choice>) -> Facet {
    Facet { key: key.to_string(), choices }
}

#[test]
fn titleize_uses_only_final_component_and_final_extension() {
    assert_eq!(titleize("dir/sub/my-file_name.tar.gz"), "My File Name.tar");
    assert_eq!(titleize("ignored/\talpha__beta--gamma .txt"), "Alpha Beta Gamma");
    assert_eq!(titleize("dir/"), "");
    assert_eq!(titleize(""), "");
    assert_eq!(titleize("already.UPPER"), "Already");
}

#[test]
fn catalog_orders_combinations_and_applies_guarantees_greedily() {
    let spec = CatalogSpec {
        prefix: "assets/hero_badges.json".into(),
        count: 3,
        facets: vec![
            facet("color", vec![choice("red", 2), choice("blue", 2)]),
            facet("size", vec![choice("s", 1), choice("m", 3)]),
        ],
        max_combinations: 4,
    };
    let original_prefix = spec.prefix.clone();
    let mut guarantees = BTreeMap::new();
    guarantees.insert(0, BTreeMap::from([("color".to_string(), "red".to_string())]));
    guarantees.insert(2, BTreeMap::from([("size".to_string(), "s".to_string())]));
    let original_guarantees = guarantees.clone();

    let badges = build_catalog(&spec, &guarantees).unwrap();
    assert_eq!(badges.len(), 3);
    assert_eq!(badges[0].ordinal, 1);
    assert_eq!(badges[0].title, "Hero Badges #1");
    assert_eq!(badges[0].traits, vec![("color".into(), "red".into()), ("size".into(), "m".into())]);
    assert_eq!(badges[1].traits, vec![("color".into(), "blue".into()), ("size".into(), "m".into())]);
    assert_eq!(badges[2].traits, vec![("color".into(), "blue".into()), ("size".into(), "s".into())]);
    assert_eq!(spec.prefix, original_prefix);
    assert_eq!(guarantees, original_guarantees);
}

#[test]
fn empty_catalog_is_empty_but_guarantees_are_still_validated() {
    let spec = CatalogSpec { prefix: String::new(), count: 0, facets: vec![], max_combinations: 1 };
    assert!(build_catalog(&spec, &BTreeMap::new()).unwrap().is_empty());

    let invalid = BTreeMap::from([(0usize, BTreeMap::new())]);
    assert!(matches!(build_catalog(&spec, &invalid), Err(CatalogError::InvalidGuarantee)));
}

#[test]
fn rejects_invalid_configuration_and_limits() {
    let duplicate_keys = CatalogSpec {
        prefix: "x".into(), count: 1, max_combinations: 2,
        facets: vec![facet("k", vec![choice("a", 1)]), facet("k", vec![choice("b", 1)])],
    };
    assert!(matches!(build_catalog(&duplicate_keys, &BTreeMap::new()), Err(CatalogError::InvalidConfig)));

    let duplicate_labels = CatalogSpec {
        prefix: "x".into(), count: 1, max_combinations: 2,
        facets: vec![facet("k", vec![choice("a", 1), choice("a", 2)])],
    };
    assert!(matches!(build_catalog(&duplicate_labels, &BTreeMap::new()), Err(CatalogError::InvalidConfig)));

    let empty_choices = CatalogSpec {
        prefix: "x".into(), count: 0, max_combinations: 1,
        facets: vec![facet("k", vec![])],
    };
    assert!(matches!(build_catalog(&empty_choices, &BTreeMap::new()), Err(CatalogError::InvalidConfig)));

    let zero_limit = CatalogSpec {
        prefix: "x".into(), count: 1, max_combinations: 0,
        facets: vec![facet("k", vec![choice("a", 1)])],
    };
    assert!(matches!(build_catalog(&zero_limit, &BTreeMap::new()), Err(CatalogError::InvalidConfig)));

    let over_limit = CatalogSpec {
        prefix: "x".into(), count: 1, max_combinations: 1,
        facets: vec![facet("k", vec![choice("a", 1), choice("b", 1)])],
    };
    assert!(matches!(build_catalog(&over_limit, &BTreeMap::new()), Err(CatalogError::CombinationLimitExceeded)));

    let over_capacity = CatalogSpec {
        prefix: "x".into(), count: 2, max_combinations: 1,
        facets: vec![facet("k", vec![choice("a", 1)])],
    };
    assert!(matches!(build_catalog(&over_capacity, &BTreeMap::new()), Err(CatalogError::CapacityExceeded)));
}

#[test]
fn rejects_unknown_unavailable_and_conflicting_guarantees() {
    let spec = CatalogSpec {
        prefix: "x".into(), count: 2, max_combinations: 2,
        facets: vec![facet("kind", vec![choice("a", 1), choice("b", 1)])],
    };
    let unknown = BTreeMap::from([(0, BTreeMap::from([("missing".into(), "a".into())]))]);
    assert!(matches!(build_catalog(&spec, &unknown), Err(CatalogError::InvalidGuarantee)));

    let unavailable = BTreeMap::from([(0, BTreeMap::from([("kind".into(), "c".into())]))]);
    assert!(matches!(build_catalog(&spec, &unavailable), Err(CatalogError::InvalidGuarantee)));

    let conflicts = BTreeMap::from([
        (0, BTreeMap::from([("kind".into(), "a".into())])),
        (1, BTreeMap::from([("kind".into(), "a".into())])),
    ]);
    assert!(matches!(build_catalog(&spec, &conflicts), Err(CatalogError::CapacityExceeded)));
}

